class Solution {
  public int minDistance(int[] houses, int k) {
    Arrays.sort(houses);
    int n = houses.length, inf = 1_000_000_000;
    // cost[i][j]: one mailbox at the median of houses i..j (peel the outer pair off each time)
    int[][] cost = new int[n][n];
    for (int len = 2; len <= n; len++) {
      for (int i = 0; i + len <= n; i++) {
        int j = i + len - 1;
        cost[i][j] = cost[i + 1][j - 1] + houses[j] - houses[i];
      }
    }
    int[][] dp = new int[k + 1][n + 1];
    for (int[] row : dp) Arrays.fill(row, inf);
    dp[0][0] = 0;
    for (int boxes = 1; boxes <= k; boxes++) {
      for (int used = boxes; used <= n; used++) {
        for (int previous = boxes - 1; previous < used; previous++) {
          if (dp[boxes - 1][previous] != inf) {
            dp[boxes][used] =
                Math.min(dp[boxes][used], dp[boxes - 1][previous] + cost[previous][used - 1]);
          }
        }
      }
    }
    return dp[k][n];
  }
}
